export function findById(id){return PRODUCTS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return PRODUCTS.slice();return PRODUCTS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return PRODUCTS.filter(x=>x.enabled!==false)}
export const COUNT=PRODUCTS.length;

